/* utils.js */
const __utils = (() => {

/**
 * 共享工具函数
 */

function parseKeyValue(stdout) {
  const data = {};
  for (const line of stdout.split(/\r?\n/)) {
    const index = line.indexOf("=");
    if (index > 0) data[line.slice(0, index)] = line.slice(index + 1);
  }
  return data;
}

function shellQuote(value) {
  return `'${String(value).replace(/'/g, "'\\''")}'`;
}

function resultMessage(result) {
  return result.stderr || result.stdout || `exit ${result.code}`;
}

function parseKeyValueLines(content, allowComments) {
  const entries = [];
  for (const line of content.split(/\r?\n/)) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    if (allowComments !== false && trimmed.startsWith("#")) continue;

    const enabled = !trimmed.startsWith("#");
    const body = enabled ? trimmed : trimmed.replace(/^#\s*/, "");
    const index = body.indexOf("=");
    if (index <= 0) continue;

    entries.push({
      prop: body.slice(0, index),
      value: body.slice(index + 1),
      enabled,
      raw: trimmed
    });
  }
  return entries;
}

function parseStateFile(content) {
  const state = {};
  for (const line of content.split(/\r?\n/)) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith("#")) continue;
    const index = trimmed.indexOf("=");
    if (index <= 0) continue;
    state[trimmed.slice(0, index)] = trimmed.slice(index + 1);
  }
  return state;
}
return { parseKeyValue, shellQuote, resultMessage, parseKeyValueLines, parseStateFile };
})();


/* bridge.js */
const __bridge = (() => {
const { shellQuote } = __utils;
const MODULE_DIR = "/data/adb/modules/dex2oat-lock";
const STATE_DIR = "/data/adb/dex2oat-lock";

let kernelSuApi;
let kernelSuApiLoaded = false;
let callbackIndex = 0;
const EXEC_TIMEOUT_MS = 15000;
const callbackRegistry = new Map();
const EXPORT_DIR = "/storage/emulated/0/Download";
const BASE64_ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
const ALLOWED_EXPORT_PATHS = new Set([
  `${EXPORT_DIR}/dex2oat-lock-config-backup.json`,
  `${EXPORT_DIR}/dex2oat-lock-diagnostic.txt`
]);

function normalizeWritePath(path) {
  return String(path || "").replace(/\/+/g, "/");
}

function isAuthorizedWritePath(path) {
  const normalized = normalizeWritePath(path);
  if (!normalized.startsWith("/") || normalized.includes("/../") || normalized.endsWith("/..")) return false;
  if (normalized === STATE_DIR || normalized.startsWith(`${STATE_DIR}/`)) return true;
  if (ALLOWED_EXPORT_PATHS.has(normalized)) return true;
  return false;
}

function encodeUtf8Bytes(value) {
  const text = String(value);
  if (typeof TextEncoder === "function") {
    return new TextEncoder().encode(text);
  }

  const bytes = [];
  for (let i = 0; i < text.length; i++) {
    let code = text.charCodeAt(i);
    if (code >= 0xd800 && code <= 0xdbff && i + 1 < text.length) {
      const next = text.charCodeAt(i + 1);
      if (next >= 0xdc00 && next <= 0xdfff) {
        code = 0x10000 + ((code - 0xd800) << 10) + (next - 0xdc00);
        i += 1;
      }
    }

    if (code <= 0x7f) {
      bytes.push(code);
    } else if (code <= 0x7ff) {
      bytes.push(0xc0 | (code >> 6), 0x80 | (code & 0x3f));
    } else if (code <= 0xffff) {
      bytes.push(0xe0 | (code >> 12), 0x80 | ((code >> 6) & 0x3f), 0x80 | (code & 0x3f));
    } else {
      bytes.push(0xf0 | (code >> 18), 0x80 | ((code >> 12) & 0x3f), 0x80 | ((code >> 6) & 0x3f), 0x80 | (code & 0x3f));
    }
  }
  return bytes;
}

function encodeBase64Binary(binary) {
  if (typeof btoa === "function") return btoa(binary);
  let output = "";
  let index = 0;
  while (index < binary.length) {
    const first = binary.charCodeAt(index++) & 0xff;
    const second = index < binary.length ? binary.charCodeAt(index++) & 0xff : NaN;
    const third = index < binary.length ? binary.charCodeAt(index++) & 0xff : NaN;
    output += BASE64_ALPHABET[first >> 2];
    output += BASE64_ALPHABET[((first & 0x03) << 4) | ((second || 0) >> 4)];
    output += second !== second ? "=" : BASE64_ALPHABET[((second & 0x0f) << 2) | ((third || 0) >> 6)];
    output += third !== third ? "=" : BASE64_ALPHABET[third & 0x3f];
  }
  return output;
}

function normalizeExecResult(result) {
  if (result == null) {
    return { code: 0, stdout: "", stderr: "" };
  }

  if (typeof result === "string") {
    return { code: 0, stdout: result, stderr: "" };
  }

  return {
    code: Number(result.code ?? result.errno ?? result.exitCode ?? 0),
    stdout: String(result.stdout ?? result.out ?? result.result ?? ""),
    stderr: String(result.stderr ?? result.err ?? "")
  };
}

async function exec(command) {
  try {
    if (!kernelSuApiLoaded) {
      kernelSuApiLoaded = true;
      try {
        kernelSuApi = await import("kernelsu");
      } catch {
        kernelSuApi = null;
      }
    }

    if (kernelSuApi && typeof kernelSuApi.exec === "function") {
      return normalizeExecResult(await kernelSuApi.exec(command));
    }

    if (globalThis.ksu && typeof globalThis.ksu.exec === "function") {
      return execWithCallback(globalThis.ksu, command);
    }

    if (globalThis.KernelSU && typeof globalThis.KernelSU.exec === "function") {
      return execWithCallback(globalThis.KernelSU, command);
    }

    const bridges = [
      globalThis.apatch,
      globalThis.APatch,
      globalThis.WebUI,
      globalThis.webui,
      globalThis.WebUIX,
      globalThis.webuiX,
      globalThis.nativeBridge
    ];

    for (const bridge of bridges) {
      if (bridge && typeof bridge.exec === "function") {
        return normalizeExecResult(await bridge.exec(command));
      }
      if (bridge && typeof bridge.shell === "function") {
        return normalizeExecResult(await bridge.shell(command));
      }
    }
  } catch (error) {
    return { code: 1, stdout: "", stderr: String(error) };
  }

  return {
    code: 127,
    stdout: "",
    stderr: "No WebUI shell bridge is available."
  };
}



function execWithCallback(bridge, command) {
  return new Promise((resolve) => {
    const callbackName = `dex2oat_exec_${Date.now()}_${callbackIndex++}`;
    const finish = (result) => {
      const entry = callbackRegistry.get(callbackName);
      if (!entry) return;
      clearTimeout(entry.timer);
      callbackRegistry.delete(callbackName);
      delete globalThis[callbackName];
      resolve(result);
    };
    const timer = setTimeout(() => {
      finish({
        code: 124,
        stdout: "",
        stderr: `WebUI shell bridge timed out after ${EXEC_TIMEOUT_MS}ms.`
      });
    }, EXEC_TIMEOUT_MS);
    callbackRegistry.set(callbackName, { timer, resolve });

    globalThis[callbackName] = (errno, stdout, stderr) => {
      finish({
        code: Number(errno || 0),
        stdout: String(stdout || ""),
        stderr: String(stderr || "")
      });
    };

    try {
      bridge.exec(command, "{}", callbackName);
    } catch (error) {
      finish({
        code: 1,
        stdout: "",
        stderr: String(error)
      });
    }
  });
}

async function readText(path) {
  const result = await exec(`cat ${shellQuote(path)} 2>/dev/null`);
  return result.code === 0 ? result.stdout.trim() : "";
}

async function writeBase64(path, content) {
  const safePath = normalizeWritePath(path);
  if (!isAuthorizedWritePath(safePath)) {
    return {
      code: 126,
      stdout: "",
      stderr: `Unauthorized WebUI write path: ${path}`
    };
  }
  const bytes = encodeUtf8Bytes(content);
  const bytesPerChunk = 6144;
  const base64Chunks = [];
  for (let i = 0; i < bytes.length; i += bytesPerChunk) {
    let chunk = "";
    for (let j = i; j < i + bytesPerChunk && j < bytes.length; j++) {
      chunk += String.fromCharCode(bytes[j]);
    }
    base64Chunks.push(encodeBase64Binary(chunk));
  }
  const quotedPath = shellQuote(safePath);
  const dirCmd = `mkdir -p ${shellQuote(safePath.replace(/\/[^/]*$/, ""))}`;
  const tempPath = `${safePath}.b64.tmp`;
  const outputTempPath = `${safePath}.write.tmp`;
  const quotedTempPath = shellQuote(tempPath);
  const quotedOutputTempPath = shellQuote(outputTempPath);
  const appendCommands = base64Chunks.map((chunk) => `printf '%s' ${shellQuote(chunk)} >> ${quotedTempPath}`);
  const writeCmd = `base64 -d ${quotedTempPath} 2>/dev/null > ${quotedOutputTempPath}`;
  const fallbackCmd = `base64 --decode ${quotedTempPath} 2>/dev/null > ${quotedOutputTempPath}`;
  let result = await exec([dirCmd, `rm -f ${quotedTempPath} ${quotedOutputTempPath}`, `: > ${quotedTempPath}`].join("; "));
  if (result.code !== 0) return result;

  for (const command of appendCommands) {
    result = await exec(command);
    if (result.code !== 0) {
      await exec(`rm -f ${quotedTempPath} ${quotedOutputTempPath}`);
      return result;
    }
  }

  result = await exec(`(${writeCmd}) || (${fallbackCmd})`);
  if (result.code === 0) {
    result = await exec(`mv -f ${quotedOutputTempPath} ${quotedPath}`);
  }
  await exec(`rm -f ${quotedTempPath} ${quotedOutputTempPath}`);
  if (result.code !== 0) return result;

  return exec(`chmod 0600 ${quotedPath} 2>/dev/null || true`);
}
return { MODULE_DIR, STATE_DIR, exec, readText, writeBase64 };
})();


/* ui.js */
const __ui = (() => {

function $(selector, root = document) {
  return root.querySelector(selector);
}

function createElement(tag, className, text) {
  const element = document.createElement(tag);
  if (className) element.className = className;
  if (text != null) element.textContent = text;
  return element;
}

function metric(label, value) {
  const node = createElement("div", "metric");
  node.append(createElement("span", "metric-label", label));
  node.append(createElement("strong", "metric-value", value));
  return node;
}

function setStatus(message, tone = "neutral") {
  const target = $("#statusMessage");
  if (!target) return;
  target.textContent = message;
  target.dataset.tone = tone;
}

function showConfirm(message) {
  return new Promise((resolve) => {
    const dialog = createElement("div", "dialog confirm-dialog");
    const panel = createElement("div", "dialog-panel");
    const title = createElement("div", "section-title");
    title.append(createElement("h2", "", "确认操作"));
    const actions = createElement("div", "dialog-actions");
    const cancel = createElement("button", "text-button", "取消");
    const ok = createElement("button", "primary-button", "确认");
    cancel.type = "button";
    ok.type = "button";
    actions.append(cancel, ok);
    panel.append(title, createElement("p", "risk-note", message), actions);
    dialog.append(panel);

    const finish = (value) => {
      if (dialog.classList.contains("is-closing")) return;
      dialog.classList.add("is-closing");
      setTimeout(() => dialog.remove(), 220);
      resolve(value);
    };
    cancel.addEventListener("click", () => finish(false));
    ok.addEventListener("click", () => finish(true));
    dialog.addEventListener("click", (event) => {
      if (event.target === dialog) finish(false);
    });
    document.body.append(dialog);
    ok.focus();
  });
}
return { $, createElement, metric, setStatus, showConfirm };
})();


/* m3-theme.js */
const __m3Theme = (() => {

/**
 * Material Design 3 — Theme Manager
 * 主题切换 + 动态配色生成
 */

/**
 * 从源色生成 M3 色彩方案 (简化版 tonal palette)
 * 完整版应使用 HCT 色彩空间，这里用 OKLCH 近似
 */
function generateColorScheme(sourceHex) {
  const { h, s, l } = hexToHsl(sourceHex);

  return {
    primary:          hslToHex(h, clamp(s, 20, 90), 50),
    onPrimary:        hslToHex(h, s > 10 ? 90 : 0, 100),
    primaryContainer: hslToHex(h, clamp(s, 15, 60), 90),
    onPrimaryContainer: hslToHex(h, clamp(s, 20, 80), 10),

    secondary:          hslToHex(h, Math.max(s * 0.12, 4), 45),
    onSecondary:        hslToHex(h, s > 10 ? 90 : 0, 100),
    secondaryContainer: hslToHex(h, Math.max(s * 0.12, 4), 90),
    onSecondaryContainer: hslToHex(h, Math.max(s * 0.15, 5), 10),

    tertiary:          hslToHex((h + 60) % 360, clamp(s * 0.6, 10, 50), 45),
    onTertiary:        hslToHex(h, s > 10 ? 90 : 0, 100),
    tertiaryContainer: hslToHex((h + 60) % 360, clamp(s * 0.5, 10, 40), 90),
    onTertiaryContainer: hslToHex((h + 60) % 360, clamp(s * 0.6, 10, 50), 10),

    error:          '#ba1a1a',
    onError:        '#ffffff',
    errorContainer: '#ffdad6',
    onErrorContainer: '#410002',
  };
}

/**
 * 将配色方案应用到 DOM
 */
function applyScheme(scheme) {
  const root = document.documentElement;
  for (const role in scheme) {
    if (!Object.prototype.hasOwnProperty.call(scheme, role)) continue;
    const value = scheme[role];
    const cssVar = `--md-sys-color-${role.replace(/([A-Z])/g, '-$1').toLowerCase()}`;
    root.style.setProperty(cssVar, value);
  }
}

/**
 * 从源色动态生成并应用配色方案
 */
function applySourceColor(hex) {
  const scheme = generateColorScheme(hex);
  applyScheme(scheme);
  writeStorage('md-source-color', hex);
}

/**
 * 读取存储的源色并应用
 */
function restoreSourceColor() {
  const saved = readStorage('md-source-color', '');
  if (saved) applySourceColor(saved);
}

/**
 * 手动切换主题 (light / dark / auto)
 */
function setTheme(mode) {
  const root = document.documentElement;
  root.removeAttribute('data-theme');

  if (mode === 'light') {
    root.setAttribute('data-theme', 'light');
  } else if (mode === 'dark') {
    root.setAttribute('data-theme', 'dark');
  }
  // 'auto' = 不设置 data-theme，靠 media query

  writeStorage('md-theme-mode', mode);
}

/**
 * 获取当前主题
 */
function getTheme() {
  return readStorage('md-theme-mode', 'auto') || 'auto';
}

/**
 * 初始化主题系统
 */
function initTheme() {
  restoreSourceColor();
  const mode = getTheme();
  if (mode !== 'auto') setTheme(mode);
}

// ── Color conversion helpers ──

function hexToHsl(hex) {
  hex = hex.replace('#', '');
  const r = parseInt(hex.substring(0, 2), 16) / 255;
  const g = parseInt(hex.substring(2, 4), 16) / 255;
  const b = parseInt(hex.substring(4, 6), 16) / 255;

  const max = Math.max(r, g, b), min = Math.min(r, g, b);
  const l = (max + min) / 2;
  let h = 0, s = 0;

  if (max !== min) {
    const d = max - min;
    s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
    if (max === r) h = ((g - b) / d + (g < b ? 6 : 0)) / 6;
    else if (max === g) h = ((b - r) / d + 2) / 6;
    else h = ((r - g) / d + 4) / 6;
  }

  return { h: Math.round(h * 360), s: Math.round(s * 100), l: Math.round(l * 100) };
}

function hslToHex(h, s, l) {
  s /= 100; l /= 100;
  const a = s * Math.min(l, 1 - l);
  const f = n => {
    const k = (n + h / 30) % 12;
    const color = l - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
    return Math.round(255 * color).toString(16).padStart(2, '0');
  };
  return `#${f(0)}${f(8)}${f(4)}`;
}

function clamp(val, min, max) {
  return Math.max(min, Math.min(max, val));
}

function readStorage(key, fallback) {
  try {
    if (typeof localStorage === 'undefined') return fallback;
    const value = localStorage.getItem(key);
    return value == null ? fallback : value;
  } catch (_error) {
    return fallback;
  }
}

function writeStorage(key, value) {
  try {
    if (typeof localStorage !== 'undefined') localStorage.setItem(key, value);
  } catch (_error) {
    // Some WebUI WebViews disable storage; theme fallback remains usable.
  }
}
return { generateColorScheme, applyScheme, applySourceColor, restoreSourceColor, setTheme, getTheme, initTheme };
})();


/* system-info.js */
const __systemInfo = (() => {
const { exec } = __bridge;
const { parseKeyValue } = __utils;
async function readSystemInfo() {
  const command = `
GETPROP=/system/bin/getprop
[ -x "$GETPROP" ] || GETPROP=getprop
UNAME=/system/bin/uname
[ -x "$UNAME" ] || UNAME=uname

prop_first() {
  for key in "$@"; do
    value=$($GETPROP "$key" 2>/dev/null)
    [ -n "$value" ] && {
      printf '%s' "$value"
      return
    }
  done
}

printf 'model=%s\n' "$(prop_first ro.product.marketname ro.product.model ro.product.device)"
printf 'android=%s\n' "$(prop_first ro.build.version.release)"
printf 'sdk=%s\n' "$(prop_first ro.build.version.sdk)"
printf 'coloros=%s\n' "$(prop_first ro.build.version.oplusrom ro.oplus.version ro.build.version.opporom)"
printf 'brand=%s\n' "$(prop_first ro.product.brand)"
printf 'manufacturer=%s\n' "$(prop_first ro.product.manufacturer)"
printf 'kernel=%s\n' "$($UNAME -r 2>/dev/null)"
if [ -d /data/adb/ksu ]; then
  printf 'root=%s\n' 'KernelSU'
elif [ -n "$KSU" ] || [ -n "$KSU_VER" ] || [ -n "$KernelSU" ]; then
  printf 'root=%s\n' 'KernelSU'
elif [ -d /data/adb/ap ]; then
  printf 'root=%s\n' 'APatch'
elif [ -n "$APATCH" ] || [ -n "$APATCH_VER" ]; then
  printf 'root=%s\n' 'APatch'
elif command -v magisk >/dev/null 2>&1; then
  printf 'root=Magisk %s\n' "$(magisk -v 2>/dev/null)"
else
  printf 'root=%s\n' 'Unknown'
fi
`.trim();

  const result = await exec(command);

  if (result.code !== 0) {
    return {
      available: false,
      error: result.stderr || result.stdout || `exit ${result.code}`,
      model: "暂不可用",
      android: "暂不可用",
      coloros: "暂不可用",
      kernel: "暂不可用",
      root: "暂不可用"
    };
  }

  const values = parseKeyValue(result.stdout);
  const coloros = values.coloros || values.oplus || "Unknown";

  return {
    available: true,
    model: values.model || values.brand || "Unknown",
    android: values.android ? `Android ${values.android}` : "Unknown",
    sdk: values.sdk || "",
    coloros,
    brand: values.brand || "",
    manufacturer: values.manufacturer || "",
    kernel: values.kernel || "Unknown",
    root: values.root || "Unknown"
  };
}
return { readSystemInfo };
})();


